#!/bin/sh
# Build NIGHTSHIFT//OS in release mode and install the `nightshift` launcher.
set -eu
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"
npm run tauri build
BIN="$ROOT/src-tauri/target/release/nightshift"
[ -x "$BIN" ] || { echo "build output missing: $BIN" >&2; exit 1; }
mkdir -p "$HOME/.local/bin" "$HOME/.local/share/applications"
cat > "$HOME/.local/bin/nightshift" <<EOF
#!/bin/sh
# NIGHTSHIFT//OS launcher (generated by scripts/install.sh)
export WEBKIT_DISABLE_DMABUF_RENDERER=1
exec setsid -f "$BIN" "\$@" >/dev/null 2>&1
EOF
chmod +x "$HOME/.local/bin/nightshift"
cat > "$HOME/.local/share/applications/nightshift.desktop" <<EOF
[Desktop Entry]
Name=NIGHTSHIFT//OS
Comment=Cyberpunk BBS coding environment
Exec=$HOME/.local/bin/nightshift
Icon=$ROOT/src-tauri/icons/icon.png
Terminal=false
Type=Application
Categories=Development;
EOF
echo "installed: run 'nightshift'"
